// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address other) public {
        // Keep the domain wide: any non-zero actor may become the owner,
        // `other` is an arbitrary unrelated address.
        vm.assume(actor != address(0));
        vm.assume(other != address(0));

        // Establish ownership: initially owner == address(0), which is the only
        // caller allowed by onlyOwner; use it to transfer ownership to `actor`.
        vm.prank(address(0));
        c.transferOwnership(actor);

        // Snapshot the owner before driving c through `owned`.
        address before = c.owner();

        // Drive c through `owned` from an arbitrary address `other` (fuzzed).
        // If `other` is not the owner the call must revert; if it is the owner
        // the call must complete WITHOUT changing the owner.
        vm.prank(other);
        try c.owned() {
            // Call succeeded: `other` was the owner (i.e. other == before).
            // Rule: owned() must not modify the owner state.
            assertTrue(c.owner() == before);
        } catch {
            // Call reverted (non-owner): the owner must still be unchanged.
            assertTrue(c.owner() == before);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // Admissible domain: any caller, any proposed new owner (kept wide).
        // Establish a known owner via the legitimate ownership-transfer path.
        // At deployment owner() == address(0), so the zero address is the
        // legitimate current owner and may perform the transfer.
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // Track the owner solely through the public getter.
        address ownerBefore = c.owner();

        // Drive c through `owned` with the fuzzed caller; record success/revert.
        bool ok;
        vm.prank(caller);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: owned() is a no-op on ownership. For ANY caller it
        // either reverts (non-owner) or, if it succeeds, the owner state must
        // still equal the value established by transferOwnership — a call to
        // owned() must never change who owns the contract, regardless of who
        // called it. The mutant breaks this: its owned() body writes
        // owner = msg.sender, so whenever owned() succeeds the owner becomes
        // the caller rather than staying the transferred-to owner.
        bool ownerUnchangedByOwned = (!ok) || (c.owner() == ownerBefore);
        assertTrue(ownerUnchangedByOwned);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address firstOwner, address lastOwner) public {
        // The initial owner is address(0); use it to seed the contract with a fuzzed owner.
        vm.prank(address(0));
        c.transferOwnership(firstOwner);

        // Drive c through `owned` from an arbitrary fuzzed caller: in the reference this
        // either reverts (caller != owner) or leaves owner unchanged (caller == owner).
        vm.prank(caller);
        try c.owned() {
            // succeeded — in the reference, owner must still be firstOwner
            assertTrue(c.owner() == firstOwner, "owned() must not change owner");
            // Set the owner via the only sanctioned path; it must take effect exactly.
            vm.prank(firstOwner);
            c.transferOwnership(lastOwner);
            assertTrue(c.owner() == lastOwner, "owner must equal last value passed to transferOwnership");
        } catch {
            // reverted — owner must be untouched and equal to firstOwner
            assertTrue(c.owner() == firstOwner, "failed owned() call must not change owner");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // WIDE admissible domain: any caller, any new owner, no tight binding.
        // 1. Establish a known owner purely through the legitimate entry point.
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // 2. Drive c through owned() from an arbitrary fuzzed caller.
        vm.prank(caller);
        try c.owned() { /* succeeded: caller was owner */ } catch { /* rejected: caller was not owner */ }

        // 3. Universal rule: owned() never mutates the owner state; only
        //    transferOwnership does. The reference preserves owner == newOwner
        //    for every admissible (caller, newOwner); the mutant writes
        //    owner = msg.sender inside owned(), diverging whenever that call
        //    completes with a caller that differs from the transferred owner.
        assertTrue(c.owner() == newOwner, "owned() must never change ownership");
    }
}
